window.V76_SCENARIOS=[{"id":"d2c","name":"D2C Fashion Brand","business":"কাল্পনিক অনলাইন ফ্যাশন স্টোর","budget":60000,"aov":3400,"margin":42,"close":24,"lesson":"ROAS ভালো মানেই লাভ নয়। Contribution margin এবং incremental scale risk দেখো।","focus":"উচ্চ ROI দেখেই পুরো বাজেট Retargeting-এ দিলে কেন বাস্তবে Audience Saturation হতে পারে?","channels":[{"name":"Google Search","spend":21000,"cpm":500,"ctr":4.1,"leadRate":8.5},{"name":"Meta Prospecting","spend":24000,"cpm":155,"ctr":1.3,"leadRate":5.0},{"name":"Meta Retargeting","spend":10000,"cpm":250,"ctr":2.7,"leadRate":11.0},{"name":"YouTube Ads","spend":5000,"cpm":130,"ctr":0.8,"leadRate":3.0}]},{"id":"local","name":"Local Dental Clinic","business":"কাল্পনিক ডেন্টাল ক্লিনিক","budget":45000,"aov":7500,"margin":48,"close":7,"lesson":"Form Lead থেকে Appointment বা Paid Client হওয়ার হারই আসল গুরুত্বপূর্ণ ফানেল ধাপ।","focus":"Lead quality, missed calls এবং booking-এর অনিশ্চয়তা বিবেচনা করে বাজেট বদলাও।","channels":[{"name":"Google Search","spend":22000,"cpm":420,"ctr":4.5,"leadRate":11.0},{"name":"Meta Prospecting","spend":15000,"cpm":160,"ctr":1.4,"leadRate":7.0},{"name":"Meta Retargeting","spend":5000,"cpm":230,"ctr":2.2,"leadRate":12.0},{"name":"YouTube Ads","spend":3000,"cpm":140,"ctr":0.85,"leadRate":3.5}]},{"id":"b2b","name":"B2B SaaS Lead Generation","business":"কাল্পনিক B2B সফটওয়্যার প্রতিষ্ঠান","budget":90000,"aov":45000,"margin":65,"close":3,"lesson":"SQL ও Closed-Won ডিল সময় নিয়ে আসে; মডেলের একই সময়ে বিক্রির অনুমান বাস্তবে মেলে না।","focus":"একটি Channel-এ কম Lead হলেও বেশি Qualified Lead এলে তা কেন গুরুত্বপূর্ণ?","channels":[{"name":"Google Search","spend":38000,"cpm":700,"ctr":3.6,"leadRate":7.0},{"name":"Meta Prospecting","spend":34000,"cpm":265,"ctr":1.05,"leadRate":4.5},{"name":"Meta Retargeting","spend":13000,"cpm":320,"ctr":1.8,"leadRate":8.0},{"name":"YouTube Ads","spend":5000,"cpm":190,"ctr":0.6,"leadRate":2.2}]}];

